class TextBoxBodyContainersetParagraph_XWPFParagraphgetCTPFikaTest {

    @Test
    void testSetParagraphInvokesGetCTP() throws Exception {
        // Create real XWPFDocument as parent
        XWPFDocument document = new XWPFDocument();

        // Create real XWPFTextBox
        XWPFTextBox textBox = document.createTextBox();

        // Get the TextBoxContent (which is the IBody implementation we need)
        TextBoxContent textBoxContent = textBox.getTextBoxContent();

        // Create a real paragraph to insert
        XWPFParagraph realParagraph = textBoxContent.createParagraph();

        // Create another real paragraph to replace at position 0
        XWPFParagraph replacementParagraph = textBoxContent.createParagraph();

        // Use reflection to access the setParagraph method
        java.lang.reflect.Method setParagraphMethod = textBoxContent.getClass()
            .getDeclaredMethod("setParagraph", XWPFParagraph.class, int.class);
        setParagraphMethod.setAccessible(true);

        // Invoke the method - this should trigger paragraph.getCTP() internally
        setParagraphMethod.invoke(textBoxContent, replacementParagraph, 0);
    }
}

