public class TOCRenderPolicyrender_XWPFRunsetTextFikaTest {

    @Test
    public void testRender() throws Exception {
        // Create real XWPFRun
        XWPFRun realRun = Mockito.mock(XWPFRun.class);

        // Create mock paragraph for parent
        XWPFParagraph mockParagraph = Mockito.mock(XWPFParagraph.class);
        when(realRun.getParent()).thenReturn(mockParagraph);

        // Create mock field run and CTField
