        when(mockParagraph.insertNewFieldRun(0)).thenReturn(mockFieldRun);

        CTSimpleField mockCTField = Mockito.mock(CTSimpleField.class);
        when(mockFieldRun.getCTField()).thenReturn(mockCTField);

        // Create mock template
        XWPFTemplate mockTemplate = Mockito.mock(XWPFTemplate.class);

        // Create mock element template
        RunTemplate mockRunTemplate = Mockito.mock(RunTemplate.class);
        when(mockRunTemplate.getRun()).thenReturn(realRun);

        // Create instance of the class under test
        Object renderPolicy = new Object() {
            public void render(ElementTemplate eleTemplate, Object data, XWPFTemplate template) {
                XWPFRun run = ((RunTemplate) (eleTemplate)).getRun();
                run.setText("", 0);
                XWPFParagraph tocPara = ((XWPFParagraph) (run.getParent()));
                XWPFFieldRun fieldRun = tocPara.insertNewFieldRun(0);
