public class XDDFOfPieChartDataaddSeries_CTPieSeraddNewCatFikaTest {

    @Test
    public void testAddSeriesInvokesAddNewCat() throws Exception {
        try (XSSFWorkbook workbook = new XSSFWorkbook()) {
            XSSFSheet sheet = workbook.createSheet();
            XSSFDrawing drawing = sheet.createDrawingPatriarch();
            XSSFClientAnchor anchor = drawing.createAnchor(0, 0, 0, 0, 0, 0, 10, 10);
            XSSFChart chart = drawing.createChart(anchor);

            XDDFOfPieChartData chartData = (XDDFOfPieChartData) chart.createData(
                org.apache.poi.xddf.usermodel.chart.ChartTypes.PIE,
                null,
                null
            );

            XDDFDataSource<String> category = XDDFDataSource.fromArray(
                new String[]{"Category1", "Category2", "Category3"}
            );
            XDDFNumericalDataSource<Double> values = XDDFNumericalDataSource.fromArray(
                new Double[]{10.0, 20.0, 30.0}
            );

            chartData.addSeries(category, values);
        }
    }
}

