        Mockito.when(ctPieSer.addNewCat()).thenReturn(null);
        Mockito.when(ctPieSer.addNewVal()).thenReturn(null);
        Mockito.when(ctPieSer.addNewIdx()).thenReturn(null);
        Mockito.when(ctPieSer.addNewOrder()).thenReturn(null);

        XDDFDataSource<?> category = Mockito.mock(XDDFDataSource.class);
        XDDFNumericalDataSource<? extends Number> values = Mockito.mock(XDDFNumericalDataSource.class);

        TestableXDDFOfPieChartData chartData = new TestableXDDFOfPieChartData(ctOfPieChart);
