public class SeriessetShowLeaderLines_CTBooleansetValFikaTest {

    @Test
    public void testSetShowLeaderLines() throws Exception {
        XWPFDocument document = new XWPFDocument();
        XWPFChart chart = document.createChart();

        CTChartSpace chartSpace = chart.getCTChartSpace();
        CTChart ctChart = chartSpace.addNewChart();
        CTPlotArea plotArea = ctChart.addNewPlotArea();
        CTLineChart lineChart = plotArea.addNewLineChart();
        lineChart.addNewVaryColors().setVal(false);

        CTLineSer series = lineChart.addNewSer();
        series.addNewIdx().setVal(0);
        series.addNewOrder().setVal(0);

        CTDLbls dLbls = series.addNewDLbls();
        CTBoolean showLeaderLines = dLbls.addNewShowLeaderLines();
        showLeaderLines.setVal(true);

        SeriesWrapper wrapper = new SeriesWrapper(series);
        wrapper.setShowLeaderLines(false);
    }

    private static class SeriesWrapper {
        private final CTLineSer series;

        public SeriesWrapper(CTLineSer series) {
            this.series = series;
        }

        public void setShowLeaderLines(boolean showLeaderLines) {
            if (!series.isSetDLbls()) {
                series.addNewDLbls();
            }
            if (series.getDLbls().isSetShowLeaderLines()) {
                series.getDLbls().getShowLeaderLines().setVal(showLeaderLines);
            } else {
                series.getDLbls().addNewShowLeaderLines().setVal(showLeaderLines);
            }
        }
    }
}

