        @Override
        public void warning(TranscoderException ex) throws TranscoderException {
            logger.warn("WARNING: " + ex.getMessage());
        }

        @Override
        public void fatalError(TranscoderException ex) throws TranscoderException {
            throw ex;
        }

        @Override
        public void error(TranscoderException ex) throws TranscoderException {
            throw ex;
        }
    });
    if (0 != width) {
        t.addTranscodingHint(PNGTranscoder.KEY_WIDTH, width * svgScale);
    }
    if (0 != maxHeight) {
        t.addTranscodingHint(PNGTranscoder.KEY_MAX_HEIGHT, maxHeight * svgScale);
    }
    try (ByteArrayInputStream instream = new ByteArrayInputStream(svgs);ByteArrayOutputStream ostream = new ByteArrayOutputStream()) {
        TranscoderInput input = new TranscoderInput(instream);
        TranscoderOutput output = new TranscoderOutput(ostream);
        t.transcode(input, output);
        ostream.flush();
        return ostream.toByteArray();
    } catch (Exception e) {
        throw new RenderException("Unable transcode from svg to png, possibly some svg attribute is not supported.", e);
    }
