package com.deepoove.poi.util;

import org.apache.batik.transcoder.Transcoder;
import org.apache.batik.transcoder.TranscoderException;
import org.apache.batik.transcoder.TranscoderInput;
import org.apache.batik.transcoder.TranscoderOutput;
import org.apache.batik.transcoder.image.PNGTranscoder;
import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;

public class SVGConvertortoPng_TranscodersetErrorHandlerFikaTest {

    @Test
    public void testSetErrorHandlerInvocation() throws TranscoderException, IOException {
        byte[] svgData = "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"100\" height=\"100\"><rect width=\"100\" height=\"100\" fill=\"blue\"/></svg>".getBytes();

        Transcoder t = new PNGTranscoder();
        t.setErrorHandler(new org.apache.batik.transcoder.ErrorHandler() {
            public void warning(TranscoderException ex) throws TranscoderException {
                // No-op
            }
            public void fatalError(TranscoderException ex) throws TranscoderException {
                throw ex;
            }
            public void error(TranscoderException ex) throws TranscoderException {
                throw ex;
            }
        });

        t.addTranscodingHint(PNGTranscoder.KEY_WIDTH, 100f);
        t.addTranscodingHint(PNGTranscoder.KEY_MAX_HEIGHT, 100f);

        try (ByteArrayInputStream instream = new ByteArrayInputStream(svgData);
             ByteArrayOutputStream ostream = new ByteArrayOutputStream()) {
            TranscoderInput input = new TranscoderInput(instream);
            TranscoderOutput output = new TranscoderOutput(ostream);
            t.transcode(input, output);
        }
    }
}

