import org.openxmlformats.schemas.drawingml.x2006.chart.CTLineSer;
import org.openxmlformats.schemas.drawingml.x2006.chart.CTBoolean;
import org.openxmlformats.schemas.drawingml.x2006.chart.CTChartFactory;
import org.openxmlformats.schemas.drawingml.x2006.chart.CTDLblsFactory;
import org.apache.xmlbeans.XmlObject;

import java.lang.reflect.Method;

public class SeriessetShowLeaderLines_CTDLblsisSetShowLeaderLinesFikaTest {

    @Test
    public void testSetShowLeaderLines() throws Exception {
        // Create a real CTLineSer instance
        CTChart chart = CTChartFactory.newInstance();
        CTPlotArea plotArea = chart.addNewPlotArea();
        CTLineChart lineChart = plotArea.addNewLineChart();
        CTLineSer series = lineChart.addNewSer();

        // Ensure series has DLbls
        if (!series.isSetDLbls()) {
            series.addNewDLbls();
        }

        // Create the class under test using reflection since we don't have its type
        Class<?> clazz = Class.forName("com.deepoove.poi.xwpf.Series");
        Object seriesInstance = clazz.getDeclaredConstructor(CTLineSer.class).newInstance(series);

        // Get the setShowLeaderLines method
        Method method = clazz.getDeclaredMethod("setShowLeaderLines", boolean.class);

        // First call to create ShowLeaderLines element
        method.invoke(seriesInstance, true);

        // Second call to trigger isSetShowLeaderLines() check
        method.invoke(seriesInstance, false);
    }
}

