import com.deepoove.poi.data.NumberingRenderData;
import com.deepoove.poi.xwpf.NiceXWPFDocument;
import com.deepoove.poi.xwpf.BodyContainer;
import com.deepoove.poi.xwpf.BodyContainerFactory;
import com.deepoove.poi.util.StyleUtils;
import com.deepoove.poi.policy.ParagraphRenderPolicy;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.math.BigInteger;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class HelperrenderNumbering_XWPFParagraphsetNumIDFikaTest {

    @Test
    public void testRenderNumbering() throws Exception {
        // Create a real XWPFRun with mocked parent chain
        XWPFRun run = Mockito.mock(XWPFRun.class);
        XWPFParagraph parentParagraph = Mockito.mock(XWPFParagraph.class);
        NiceXWPFDocument document = Mockito.mock(NiceXWPFDocument.class);

        Mockito.when(run.getParent()).thenReturn(parentParagraph);
        Mockito.when(parentParagraph.getDocument()).thenReturn(document);

        // Mock the numbering ID generation
        BigInteger mockNumId = new BigInteger("1");
        Mockito.when(document.addNewMultiLevelNumberingId(Mockito.any(NumberingFormat[].class)))
               .thenReturn(mockNumId);

        // Create real NumberingRenderData with items that have non-normal level
        NumberingItemRenderData item = new NumberingItemRenderData();
        item.setLevel(1); // Non-normal level to trigger the target method
        item.setItem("Test item");

        List<NumberingItemRenderData> items = new ArrayList<>();
        items.add(item);

        NumberingRenderData data = new NumberingRenderData();
        data.setItems(items);
        data.setFormats(Arrays.asList(NumberingFormat.DECIMAL));

        // Mock BodyContainer to return a real paragraph when insertNewParagraph is called
        BodyContainer bodyContainer = Mockito.mock(BodyContainer.class);
        Mockito.when(BodyContainerFactory.getBodyContainer(run)).thenReturn(bodyContainer);

        XWPFParagraph realParagraph = new XWPFParagraph(
            org.apache.poi.xwpf.usermodel.XWPFDocument.create().getDocument().getBody().addNewP(),
            org.apache.poi.xwpf.usermodel.XWPFDocument.create().getDocument().getBody()
        );
        Mockito.when(bodyContainer.insertNewParagraph(run)).thenReturn(realParagraph);

        // Mock StyleUtils.styleRun to avoid NPE
        Mockito.doNothing().when(StyleUtils.class);
        StyleUtils.styleRun(Mockito.any(XWPFRun.class), Mockito.any(XWPFRun.class));

        // Mock ParagraphRenderPolicy.Helper.renderParagraph to avoid NPE
        Mockito.mockStatic(ParagraphRenderPolicy.Helper.class);
        Mockito.when(ParagraphRenderPolicy.Helper.renderParagraph(Mockito.any(XWPFRun.class), Mockito.any()))
               .thenReturn(null);

        // Execute the method - this should trigger paragraph.setNumID(mockNumId)
        Helper.renderNumbering(run, data);
    }
}

