import org.apache.poi.xddf.usermodel.chart.ChartTypes;
import org.apache.poi.xddf.usermodel.chart.XDDFChart;
import org.apache.poi.xwpf.usermodel.XWPFChart;
import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.junit.jupiter.api.Test;
import java.io.ByteArrayOutputStream;
import java.util.Arrays;

public class XDDFOfPieChartDatasetVaryColors_CTOfPieChartgetVaryColorsFikaTest {

    @Test
    public void testSetVaryColors() throws Exception {
        try (XWPFDocument document = new XWPFDocument()) {
            XWPFChart xwpfChart = document.createChart();
            XDDFChart xddfChart = xwpfChart.getXDDFChart();

            XDDFDataSource<String> categories = XDDFDataSourcesFactory.fromArray(
                new String[]{"Category 1", "Category 2", "Category 3"}
            );
            XDDFNumericalDataSource<Double> values = XDDFDataSourcesFactory.fromArray(
                new Double[]{10.0, 20.0, 30.0}
            );

            XDDFChartData data = xddfChart.createData(ChartTypes.PIE, null, null);
            data.addSeries(categories, values);
            xddfChart.plot(data);

            data.setVaryColors(true);
            data.setVaryColors(false);

            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            document.write(baos);
        }
    }
}

