import com.deepoove.poi.policy.AttachmentRenderPolicy.AttachmentRenderData;
import com.deepoove.poi.render.RenderContext;
import com.deepoove.poi.xwpf.NiceXWPFDocument;
import org.apache.poi.xwpf.usermodel.XWPFRun;
import org.apache.xmlbeans.XmlObject;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTR;

import java.io.ByteArrayInputStream;
import java.util.UUID;
import java.util.concurrent.ThreadLocalRandom;

import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
public class AttachmentRenderPolicydoRender_CTRsetFikaTest {

    @Mock
    private NiceXWPFDocument mockDoc;

    @Mock
    private XWPFRun mockRun;

    @Mock
    private CTR mockCtr;

    @Mock
    private AttachmentRenderData mockData;

    @Test
    public void testDoRender() throws Exception {
        AttachmentRenderPolicy policy = new AttachmentRenderPolicy();

        RenderContext<AttachmentRenderData> context = mock(RenderContext.class);
        when(context.getXWPFDocument()).thenReturn(mockDoc);
        when(context.getRun()).thenReturn(mockRun);
        when(context.getData()).thenReturn(mockData);

        when(mockRun.getCTR()).thenReturn(mockCtr);

        when(mockData.getFileType()).thenReturn(AttachmentType.DOCX);
        when(mockData.readAttachmentData()).thenReturn(new byte[]{1, 2, 3, 4});
        when(mockData.getIcon()).thenReturn(null);

        when(mockDoc.addPictureData(any(byte[].class), anyInt())).thenReturn("rId1");
        when(mockDoc.addEmbeddData(any(byte[].class), anyString(), anyString())).thenReturn("rId2");

        policy.doRender(context);
    }
}

