    private XWPFRun mockRun;

    @Mock
    private CTR mockCtr;

    @Mock
    private AttachmentRenderData mockData;

    @Mock
    private PictureRenderData mockIcon;

    @Test
    public void testDoRender() throws Exception {
        AttachmentRenderPolicy policy = new AttachmentRenderPolicy();

        RenderContext<AttachmentRenderData> mockContext = mock(RenderContext.class);
        when(mockContext.getXWPFDocument()).thenReturn(mockDoc);
        when(mockContext.getRun()).thenReturn(mockRun);
        when(mockContext.getData()).thenReturn(mockData);

        when(mockRun.getCTR()).thenReturn(mockCtr);

        when(mockData.getFileType()).thenReturn(AttachmentType.EXCEL);
        when(mockData.readAttachmentData()).thenReturn(new byte[]{1, 2, 3});
        when(mockData.getIcon()).thenReturn(null);

        when(mockDoc.addPictureData(any(byte[].class), anyInt())).thenReturn("rId1");
        when(mockDoc.addEmbeddData(any(byte[].class), anyString(), anyString())).thenReturn("rId2");

        policy.doRender(mockContext);
    }

    // Helper mock classes since they're not available in the test environment
    public static class AttachmentRenderData {
        public AttachmentType getFileType() { return null; }
        public byte[] readAttachmentData() { return null; }
        public PictureRenderData getIcon() { return null; }
        public String contentType() { return "application/vnd.ms-excel"; }
        public String ext() { return ".xlsx"; }
        public String programId() { return "Excel.Sheet.12"; }
        public String icon() { return "base64icon"; }
    }

    public enum AttachmentType {
        EXCEL {
            @Override public String contentType() { return "application/vnd.ms-excel"; }
            @Override public String ext() { return ".xlsx"; }
            @Override public String programId() { return "Excel.Sheet.12"; }
            @Override public String icon() { return "base64icon"; }
        };

        public abstract String contentType();
        public abstract String ext();
        public abstract String programId();
        public abstract String icon();
    }

    public static class PictureRenderData {
        public byte[] readPictureData() { return null; }
        public PictureType getPictureType() { return null; }
        public PictureStyle getPictureStyle() { return null; }
    }

    public static class PictureStyle {
        public int getWidth() { return 64; }
        public int getHeight() { return 64; }
    }

    public static class Units {
        public static double pixelToPoints(int pixels) { return pixels * 0.75; }
    }
}

