public XWPFStructuredDocumentTagContent(CTSdtContentRun sdtRun, IBody part, XWPFStructuredDocumentTag parent) {
    this.sdtContentRun = sdtRun;
    this.sdt = parent;
    if (sdtRun == null) {
        return;
