            sdtElements.add(t);
        } else if (o instanceof CTSdtBlock) {
            XWPFStructuredDocumentTag c = new XWPFStructuredDocumentTag(((CTSdtBlock) (o)), this);
            sdtElements.add(c);
        } else if (o instanceof CTR) {
            XWPFRun run = new XWPFRun(((CTR) (o)), this);
            // runs.add(run);
            sdtElements.add(run);
        }
    } 
    cursor.dispose();
}

