        Mockito.when(paragraph.getCTP()).thenReturn(ctp);

        // Create mock runs that include XWPFSDT instances to pass the filter
        XWPFRun mockSdtRun = Mockito.mock(XWPFRun.class, Mockito.withSettings()
                .extraInterfaces(org.apache.poi.xwpf.usermodel.XWPFSDT.class));

        // Return a stream with the mock SDT run
        Mockito.when(paragraph.getIRuns()).thenReturn(List.of(mockSdtRun));

        // Mock getBody() to return null (not needed for the test)
        Mockito.when(paragraph.getBody()).thenReturn(null);

