        XWPFDocument document = new XWPFDocument();

        NiceXWPFDocument niceDocument = new NiceXWPFDocument(document);

        NumberingFormat fmt1 = new NumberingFormat();
        fmt1.setNumFmt(STNumberFormat.DECIMAL.intValue());
        fmt1.setLvlText("%1.");

