        for (int i = 0; i < insertPostionCursor; i++) {
            XWPFRun currRun = runs.get(i);
            if (!((currRun instanceof XWPFHyperlinkRun) || (currRun instanceof XWPFFieldRun))) {
                rPos++;
            }
        }
