    sdtContentRun.setRArray(rPos, xwpfRun.getCTR());
    // runs
    for (int i = 0; i < runs.size(); i++) {
        XWPFRun ele = runs.get(i);
        if (ele == source) {
            runs.set(i, xwpfRun);
