import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTP;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTR;

import java.util.List;

public class CellBodyContainerinsertNewTable_XWPFTablecreateRowFikaTest {

    @Test
    public void testInsertNewTableInvokesCreateRow() throws Exception {
        // Create minimal document structure
        XWPFDocument document = new XWPFDocument();
        XWPFParagraph paragraph = document.createParagraph();
        XWPFRun run = paragraph.createRun();
        run.setText("test");

        // Create a custom table that will be inserted
        XWPFTable table = document.createTable();

        // Create a custom implementation that overrides insertNewTbl to return our table
        CellBodyContainer container = new CellBodyContainer() {
            @Override
            protected XWPFTable insertNewTbl(org.apache.xmlbeans.XmlCursor cursor) {
                // Return the table we created
                return table;
            }

            @Override
            public XWPFTable insertNewTable(XWPFRun run, int row, int col) {
                return super.insertNewTable(run, row, col);
            }
        };

        // Invoke the method - this should trigger table.createRow() when row > 0
        container.insertNewTable(run, 2, 1);

        // Clean up
        document.close();
    }

    // Minimal implementation of abstract class to make test compile
    private abstract static class CellBodyContainer {
        public abstract XWPFTable insertNewTable(XWPFRun run, int row, int col);
        protected abstract XWPFTable insertNewTbl(org.apache.xmlbeans.XmlCursor cursor);
    }
