        return;
    }
    XmlCursor cursor = block.newCursor();
    cursor.selectPath("./*");
    while (cursor.toNextSelection()) {
        XmlObject o = cursor.getObject();
        if (o instanceof CTP) {
            XWPFParagraph p = new XWPFParagraph(((CTP) (o)), this);
            paragraphs.add(p);
            sdtElements.add(p);
        } else if (o instanceof CTTbl) {
