package com.deepoove.poi.policy.reference;

import com.deepoove.poi.XWPFTemplate;
import com.deepoove.poi.data.ChartMultiSeriesRenderData;
import com.deepoove.poi.data.SeriesRenderData;
import com.deepoove.poi.template.ChartTemplate;
import com.deepoove.poi.template.MetaTemplate;
import org.apache.poi.xddf.usermodel.chart.*;
import org.apache.poi.xwpf.usermodel.XWPFChart;
import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.util.ArrayList;
import java.util.List;

public class MultiSeriesChartTemplateRenderPolicydoRender_XWPFChartsetSheetTitleFikaTest {

    @Test
    public void testDoRender() throws Exception {
        // Create real chart template
        ChartTemplate chartTemplate = Mockito.mock(ChartTemplate.class);

        // Create real XWPFChart with workbook
        XWPFDocument document = new XWPFDocument();
        XWPFChart chart = document.createChart();

        // Setup chart series
        XDDFScatterChartData scatterData = (XDDFScatterChartData) chart.createData(
            ChartTypes.SCATTER, null, null
        );

        // Create categories and values
        Double[] categories = {1.0, 2.0, 3.0};
        Double[] values = {10.0, 20.0, 30.0};

        XDDFNumericalDataSource<Double> catData = XDDFDataSourcesFactory.fromArray(categories);
        XDDFNumericalDataSource<Double> valData = XDDFDataSourcesFactory.fromArray(values);

        // Add series to chart
        scatterData.addSeries(catData, valData);

        Mockito.when(chartTemplate.getChart()).thenReturn(chart);

        // Create render data
        ChartMultiSeriesRenderData renderData = ChartMultiSeriesRenderData.builder()
            .addSeries("Series1", new Double[]{1.0, 2.0, 3.0})
            .categories("Cat1", "Cat2", "Cat3")
            .build();

        // Create template
        XWPFTemplate template = Mockito.mock(XWPFTemplate.class);
        XWPFDocument templateDoc = new XWPFDocument();
        Mockito.when(template.getXWPFDocument()).thenReturn(templateDoc);

        // Create policy instance
        MultiSeriesChartTemplateRenderPolicy policy = new MultiSeriesChartTemplateRenderPolicy();

        // Execute method - this should trigger chart.setSheetTitle()
        policy.doRender(chartTemplate, renderData, template);

        // Cleanup
        document.close();
        templateDoc.close();
    }
}

