        CTTblPr tblPr = Mockito.mock(CTTblPr.class);
        CTTblBorders tblBorders = Mockito.mock(CTTblBorders.class);

        CTBorder bottomBorder = Mockito.mock(CTBorder.class);
        CTBorder leftBorder = Mockito.mock(CTBorder.class);
        CTBorder topBorder = Mockito.mock(CTBorder.class);
        CTBorder rightBorder = Mockito.mock(CTBorder.class);
        CTBorder insideHBorder = Mockito.mock(CTBorder.class);
        CTBorder insideVBorder = Mockito.mock(CTBorder.class);

        Mockito.when(tblPr.getTblBorders()).thenReturn(tblBorders);
        Mockito.when(tblBorders.isSetBottom()).thenReturn(true);
        Mockito.when(tblBorders.isSetLeft()).thenReturn(true);
        Mockito.when(tblBorders.isSetTop()).thenReturn(true);
        Mockito.when(tblBorders.isSetRight()).thenReturn(true);
        Mockito.when(tblBorders.isSetInsideH()).thenReturn(false);
        Mockito.when(tblBorders.isSetInsideV()).thenReturn(true);

        Mockito.when(tblBorders.getBottom()).thenReturn(bottomBorder);
        Mockito.when(tblBorders.getLeft()).thenReturn(leftBorder);
        Mockito.when(tblBorders.getTop()).thenReturn(topBorder);
        Mockito.when(tblBorders.getRight()).thenReturn(rightBorder);
        Mockito.when(tblBorders.getInsideH()).thenReturn(insideHBorder);
        Mockito.when(tblBorders.getInsideV()).thenReturn(insideVBorder);

