package com.deepoove.poi.util;

import org.apache.poi.xwpf.usermodel.XWPFTableRow;
import org.apache.poi.xwpf.usermodel.XWPFOnOff;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTRow;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTrPr;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTOnOff;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTHeight;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.STHeightRule;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

public class StyleUtilsstyleTableRow_CTTrPrsizeOfTblHeaderArrayFikaTest {

    @Test
    public void testStyleTableRowInvokesSizeOfTblHeaderArray() {
        RowStyle rowStyle = new RowStyle();
        rowStyle.setRepeated(true);

        XWPFTableRow row = Mockito.mock(XWPFTableRow.class);
        CTRow ctRow = Mockito.mock(CTRow.class);
        CTTrPr ctTrPr = Mockito.mock(CTTrPr.class);
        CTOnOff ctOnOff = Mockito.mock(CTOnOff.class);

        Mockito.when(row.getCtRow()).thenReturn(ctRow);
        Mockito.when(ctRow.isSetTrPr()).thenReturn(true);
        Mockito.when(ctRow.getTrPr()).thenReturn(ctTrPr);
        Mockito.when(ctTrPr.sizeOfTblHeaderArray()).thenReturn(0);
        Mockito.when(ctTrPr.addNewTblHeader()).thenReturn(ctOnOff);

        StyleUtils.styleTableRow(row, rowStyle);
    }

    private static class RowStyle {
        private int height = 0;
        private String heightRule = "auto";
        private boolean repeated = false;
        private boolean breakAcrossPage = false;

        public int getHeight() {
            return height;
        }

        public void setHeight(int height) {
            this.height = height;
        }

        public String getHeightRule() {
            return heightRule;
        }

        public void setHeightRule(String heightRule) {
            this.heightRule = heightRule;
        }

        public boolean isRepeated() {
            return repeated;
        }

        public void setRepeated(boolean repeated) {
            this.repeated = repeated;
        }

        public boolean isBreakAcrossPage() {
            return breakAcrossPage;
        }

        public void setBreakAcrossPage(boolean breakAcrossPage) {
            this.breakAcrossPage = breakAcrossPage;
        }
    }
}

