package com.deepoove.poi.util;

import org.apache.poi.xwpf.usermodel.XWPFRun;
import org.apache.poi.xwpf.usermodel.UnderlinePatterns;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import static org.mockito.Mockito.when;

public class StyleUtilsstyleRun_StringUtilsisNotEmptyFikaTest {

    @Test
    public void testStyleRun() {
        XWPFRun srcRun = Mockito.mock(XWPFRun.class);
        XWPFRun destRun = Mockito.mock(XWPFRun.class);

        when(srcRun.getStyle()).thenReturn("CustomStyle");
        when(srcRun.isBold()).thenReturn(true);
        when(srcRun.getColor()).thenReturn("FF0000");
        when(srcRun.getCharacterSpacing()).thenReturn(5);
        when(srcRun.getFontFamily(FontCharRange.ascii)).thenReturn("Arial");
        when(srcRun.getFontFamily(FontCharRange.eastAsia)).thenReturn("MS Gothic");
        when(srcRun.getFontFamily(FontCharRange.hAnsi)).thenReturn("Calibri");
        when(srcRun.getFontFamily(FontCharRange.cs)).thenReturn("Times New Roman");
        when(srcRun.getFontSizeAsDouble()).thenReturn(12.0);
        when(srcRun.isItalic()).thenReturn(true);
        when(srcRun.isStrikeThrough()).thenReturn(true);
        when(srcRun.getUnderline()).thenReturn(UnderlinePatterns.SINGLE);
        when(srcRun.getUnderlineColor()).thenReturn("00FF00");

        StyleUtils.styleRun(destRun, srcRun);
    }
}

