        XWPFParagraph paragraph = Mockito.mock(XWPFParagraph.class);

        // Create real CTP object
        CTP ctp = CTP.Factory.newInstance();

        // Create real CTPPr object
        CTPPr pr = ctp.addNewPPr();

        // Create real CTPBdr object
        CTPBdr ct = pr.addNewPBdr();

        // Create real CTBorder for left border
        CTBorder leftBorder = ct.addNewLeft();
        leftBorder.setVal(org.openxmlformats.schemas.wordprocessingml.x2006.main.STBorder.SINGLE);

        // Mock paragraph to return real CTP
        when(paragraph.getCTP()).thenReturn(ctp);

        // Mock paragraph.isWordWrapped() to return false to avoid affecting flow
        when(paragraph.isWordWrapped()).thenReturn(false);

