import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTPPr;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.math.BigInteger;

import com.deepoove.poi.util.StyleUtils;
import com.deepoove.poi.data.style.ParagraphStyle;

public class StyleUtilsstylePpr_CTPPraddNewShdFikaTest {

    @Test
    public void testStylePprInvokesAddNewShd() throws Exception {
        XWPFParagraph paragraph = Mockito.mock(XWPFParagraph.class);
        CTP ctP = Mockito.mock(CTP.class);
        CTPPr ctPPr = Mockito.mock(CTPPr.class);

        Mockito.when(paragraph.getCTP()).thenReturn(ctP);
        Mockito.when(ctP.isSetPPr()).thenReturn(false);
        Mockito.when(ctP.addNewPPr()).thenReturn(ctPPr);
        Mockito.when(ctPPr.isSetShd()).thenReturn(false);

        ParagraphStyle style = ParagraphStyle.builder()
                .withBackgroundColor("FF0000")
                .build();

        StyleUtils.stylePpr(paragraph, style);
    }
}

