class AbstractRenderPolicy_PictureRenderPolicyreThrowException_XWPFRunsetTextFikaTest {

    @Test
    void testReThrowException() throws Exception {
        RenderContext<PictureRenderData> context = Mockito.mock(RenderContext.class);
        XWPFRun run = Mockito.mock(XWPFRun.class);
        PictureRenderData data = Mockito.mock(PictureRenderData.class);

        Mockito.when(context.getRun()).thenReturn(run);
        Mockito.when(context.getData()).thenReturn(data);
        Mockito.when(data.getAltMeta()).thenReturn("test alt text");

        AbstractRenderPolicy<PictureRenderData> policy = new AbstractRenderPolicy<PictureRenderData>() {
            @Override
            protected void reThrowException(RenderContext<PictureRenderData> context, Exception e) {
                logger.info(("Render picture " + context.getEleTemplate()) + " error: {}", e.getMessage());
                String alt = context.getData().getAltMeta();
                context.getRun().setText(alt, 0);
            }
        };

        policy.reThrowException(context, new Exception("test exception"));
    }
}

