@Override
public void setVaryColors(Boolean varyColors) {
    if (varyColors == null) {
        if (chart.isSetVaryColors()) {
            chart.unsetVaryColors();
        }
    } else if (chart.isSetVaryColors()) {
        chart.getVaryColors().setVal(varyColors);
    } else {
        chart.addNewVaryColors().setVal(varyColors);
    }
}

