        XDDFChartData data = Mockito.mock(XDDFChartData.class);
        XDDFChartData.Series series = Mockito.mock(XDDFChartData.Series.class);
        XDDFDataSource<?> categoryData = Mockito.mock(XDDFDataSource.class);
        XDDFNumericalDataSource<?> valuesData = Mockito.mock(XDDFNumericalDataSource.class);
        XSSFSheet sheet = Mockito.mock(XSSFSheet.class);

        CTAxDataSource axDataSource = Mockito.mock(CTAxDataSource.class);

        Mockito.when(chart.getWorkbook()).thenReturn(null);
        Mockito.when(data.getSeries()).thenReturn(Collections.singletonList(series));
        Mockito.when(series.getCategoryData()).thenReturn(categoryData);
        Mockito.when(series.getValuesData()).thenReturn(valuesData);
        Mockito.when(categoryData.isNumeric()).thenReturn(false);
        Mockito.when(axDataSource.isSetNumRef()).thenReturn(false);
        Mockito.when(axDataSource.isSetNumLit()).thenReturn(false);

