    bodyElements = new ArrayList<>();
    paragraphs = new ArrayList<>();
    XmlCursor cursor = ctTxbxContent.newCursor();
    cursor.selectPath("./*");
    while (cursor.toNextSelection()) {
        XmlObject o = cursor.getObject();
        if (o instanceof CTP) {
