                if (inline.getDocPr() != null) {
                    long id = inline.getDocPr().getId();
                    long reserve = this.idenifierManagerWrapper.reserve(id);
                    if (adjustDoc && (id != reserve)) {
                        inline.getDocPr().setId(reserve);
                        xmlObject.set(ctDrawing);
