    XDDFDataSource<?> categoriesData = null;
    if (pie instanceof XDDFScatterChartData) {
        categoriesData = createNumbericalDataSource(chart, toNumberArray(data.getCategories()), 0);
    } else {
        categoriesData = createStringDataSource(chart, data.getCategories(), 0);
    }
    XDDFNumericalDataSource<? extends Number> valuesData = createNumbericalDataSource(chart, seriesDatas.getValues(), 1);
    XDDFChartData.Series currentSeries = pie.getSeries(0);
    currentSeries.replaceData(categoriesData, valuesData);
    currentSeries.setTitle(seriesDatas.getName(), chart.setSheetTitle(seriesDatas.getName(), 1));
    updateCTTable(chart.getWorkbook().getSheetAt(0), Arrays.asList(seriesDatas));
    plot(chart, pie);
    setTitle(chart, data.getChartTitle());
    setAxisTitle(chart, data.getxAxisTitle(), data.getyAxisTitle());
}

@SuppressWarnings("deprecation")
protected void plot(XWPFChart chart, XDDFChartData data) throws Exception {
    XSSFSheet sheet = chart.getWorkbook().getSheetAt(0);
    Method method = XDDFChart.class.getDeclaredMethod("fillSheet", XSSFSheet.class, XDDFDataSource.class, XDDFNumericalDataSource.class);
    method.setAccessible(true);
    for (XDDFChartData.Series series : data.getSeries()) {
        boolean numeric = series.getCategoryData().isNumeric();
        if (!numeric) {
            Method getAxDSMethod = series.getClass().getDeclaredMethod("getAxDS");
            getAxDSMethod.setAccessible(true);
            CTAxDataSource axDataSource = ((CTAxDataSource) (getAxDSMethod.invoke(series)));
            if (axDataSource.isSetNumRef()) {
                axDataSource.unsetNumRef();
            }
            // PATH: Test should invoke the next CTAxDataSource.isSetNumLit(...) [step in execution path]
            if (axDataSource.isSetNumLit()) {
                axDataSource.unsetNumLit();
            }
        }
        series.plot();
        method.invoke(chart, sheet, series.getCategoryData(), series.getValuesData());
    }
}

