class TableToolsgetTblPr_CTTbladdNewTblPrFikaTest3 {

    @Test
    void testGetTblPr() throws Exception {
        XWPFDocument document = new XWPFDocument();
        XWPFTable table = document.createTable();

        // Create a table with no existing tblPr
        XWPFTableRow row = table.getRow(0);
        if (row == null) {
            row = table.createRow();
        }
        XWPFTableCell cell = row.getCell(0);
        if (cell == null) {
            cell = row.createCell();
        }

        // Force table to have no tblPr by serializing and deserializing
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        document.write(baos);
        ByteArrayInputStream bais = new ByteArrayInputStream(baos.toByteArray());
        XWPFDocument newDocument = new XWPFDocument(bais);
        XWPFTable newTable = newDocument.getTables().get(0);

        // This should trigger the addNewTblPr() call
        TableTools.getTblPr(newTable);

        newDocument.close();
        document.close();
    }
}

