public (RunBodyContext context, Pattern pattern) // PATH: Test should invoke the next RunningRunBody.buildRunEdge(...) [step in execution path]
{
    this.runBodyContext = context;
    this.runs = context.getRuns();
    if ((null == runs) || runs.isEmpty()) {
        return;
    }
    Matcher matcher = pattern.matcher(getText(context));
    if (matcher.find()) {
        refactorBody();
    }
    buildRunEdge(pattern);
}

private void buildRunEdge(Pattern pattern) {
    // find all templates
    Matcher matcher = pattern.matcher(getText(runBodyContext));
    while (matcher.find()) {
        // PATH: Test should invoke the next ImmutablePair.of(...) [step in execution path]
        pairs.add(ImmutablePair.of(new RunEdge(matcher.start(), matcher.group()), new RunEdge(matcher.end(), matcher.group())));
    } 
    if (pairs.isEmpty()) {
        return;
    }
    boolean endflag = false;
    int size = runs.size();
    int cursor = 0;
    int pos = 0;
    // find the run where all templates are located
    Pair<RunEdge, RunEdge> pair = pairs.get(pos);
    RunEdge startEdge = pair.getLeft();
    RunEdge endEdge = pair.getRight();
    int start = startEdge.getAllEdge();
