package com.deepoove.poi.plugin.table;

import org.apache.poi.xwpf.usermodel.XWPFTable;
import org.apache.poi.xwpf.usermodel.XWPFTableRow;
import org.apache.poi.xwpf.usermodel.XWPFTableCell;
import org.apache.poi.xwpf.usermodel.TableWidthType;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTblGrid;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTblGridCol;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.lang.reflect.Method;
import java.math.BigInteger;

public class MultipleColumnTableRenderPolicyprocessLoopColWidth_CTTblGridColsetWFikaTest {

    @Test
    public void testProcessLoopColWidth() throws Exception {
        // Create mock table and row
        XWPFTable table = Mockito.mock(XWPFTable.class);
        XWPFTableRow row = Mockito.mock(XWPFTableRow.class);

        // Create mock template cell with required properties
        XWPFTableCell templateCell = Mockito.mock(XWPFTableCell.class);
        Mockito.when(templateCell.getWidth()).thenReturn(1000); // width in DXA
        Mockito.when(templateCell.getWidthType()).thenReturn(TableWidthType.DXA);

        // Mock row.getCell to return our template cell
        Mockito.when(row.getCell(Mockito.anyInt())).thenReturn(templateCell);

        // Create real CTTblGrid that will produce real CTTblGridCol objects
        CTTblGrid tblGrid = CTTblGrid.Factory.newInstance();

        // Mock TableTools.getTblGrid to return our real CTTblGrid
        // We need to use reflection to call the private method
        Class<?> tableToolsClass = Class.forName("com.deepoove.poi.util.TableTools");
        Method getTblGridMethod = tableToolsClass.getDeclaredMethod("getTblGrid", XWPFTable.class);
        getTblGridMethod.setAccessible(true);

        // Create a spy on the class to intercept the method call
        Object tableToolsSpy = Mockito.spy(tableToolsClass);
        Mockito.doReturn(tblGrid).when((Class<?>)tableToolsSpy).getMethod("getTblGrid", XWPFTable.class)
                .invoke(tableToolsSpy, table);

        // Create instance of the class under test
        Object policyInstance = Class.forName("com.deepoove.poi.plugin.table.MultipleColumnTableRenderPolicy")
                .getDeclaredConstructor().newInstance();

        // Get the private method using reflection
        Method processLoopColWidthMethod = policyInstance.getClass()
                .getDeclaredMethod("processLoopColWidth", 
                        XWPFTable.class, XWPFTableRow.class, int.class, int.class, int.class);
        processLoopColWidthMethod.setAccessible(true);

        // Invoke the method with parameters that will trigger the target third-party method
        // templateColIndex=0, dataSize=2, loopColumnNum=1 ensures we enter the loop
        processLoopColWidthMethod.invoke(policyInstance, table, row, 0, 2, 1);
    }
}

