import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTFonts;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.math.BigDecimal;
import java.math.RoundingMode;

import com.deepoove.poi.data.style.Style;
import com.deepoove.poi.data.style.UnderlinePatterns;

import static org.mockito.Mockito.when;

public class StyleUtilsstyleParaRpr_CTParaRPraddNewRFontsFikaTest {

    @Test
    public void testStyleParaRprInvokesAddNewRFonts() throws Exception {
        // Create a real CTParaRPr object
        CTParaRPr pr = CTParaRPr.Factory.newInstance();

        // Create a mock Style object that will trigger the font path
        Style style = Mockito.mock(Style.class);

        // Configure style to ensure we reach the font section
        when(style.getFontFamily()).thenReturn("Arial");
        when(style.getWesternFontFamily()).thenReturn("Times New Roman");

        // Ensure other style properties don't cause early returns
        when(style.getColor()).thenReturn(null);
        when(style.isItalic()).thenReturn(null);
        when(style.isBold()).thenReturn(null);
        when(style.getFontSize()).thenReturn(0);
        when(style.isStrike()).thenReturn(null);
        when(style.getUnderlinePatterns()).thenReturn(null);

        // Invoke the private method using reflection
        java.lang.reflect.Method method = getClass().getDeclaringClass()
            .getDeclaredMethod("styleParaRpr", CTParaRPr.class, Style.class);
        method.setAccessible(true);
        method.invoke(null, pr, style);
    }
}

