public void doRender(ChartTemplate eleTemplate, ChartSingleSeriesRenderData data, XWPFTemplate template) throws Exception // PATH: Test should invoke the next AbstractChartTemplateRenderPolicy.updateCTTable(...) [step in execution path]
{
    XWPFChart chart = eleTemplate.getChart();
    XDDFChartData pie = ChartUtils.getChartSeries(chart).get(0);
    SeriesRenderData seriesDatas = data.getSeriesData();
    XDDFDataSource<?> categoriesData = null;
    if (pie instanceof XDDFScatterChartData) {
        categoriesData = createNumbericalDataSource(chart, toNumberArray(data.getCategories()), 0);
    } else {
        categoriesData = createStringDataSource(chart, data.getCategories(), 0);
    }
    XDDFNumericalDataSource<? extends Number> valuesData = createNumbericalDataSource(chart, seriesDatas.getValues(), 1);
    XDDFChartData.Series currentSeries = pie.getSeries(0);
    currentSeries.replaceData(categoriesData, valuesData);
    currentSeries.setTitle(seriesDatas.getName(), chart.setSheetTitle(seriesDatas.getName(), 1));
    updateCTTable(chart.getWorkbook().getSheetAt(0), Arrays.asList(seriesDatas));
    plot(chart, pie);
    setTitle(chart, data.getChartTitle());
    setAxisTitle(chart, data.getxAxisTitle(), data.getyAxisTitle());
}

protected void updateCTTable(XSSFSheet sheet, List<SeriesRenderData> seriesDatas) {
    final int seriesSize = seriesDatas.size();
    final int numOfPoints = seriesDatas.get(0).getValues().length;
    // PATH: Test should invoke the next AbstractChartTemplateRenderPolicy.getSheetTable(...) [step in execution path]
    CTTable ctTable = getSheetTable(sheet);
    String prefix = (seriesSize >= 26) ? String.valueOf(((char) ('A' + ((seriesSize / 26) - 1)))) : "";
    char c = ((char) ('A' + (seriesSize % 26)));
    String ref = (("A1:" + prefix) + c) + (numOfPoints + 1);
    ctTable.setRef(ref);
    CTTableColumns tableColumns = ctTable.getTableColumns();
    tableColumns.setCount(seriesSize + 1);
    int size = tableColumns.sizeOfTableColumnArray();
    for (int i = size - 1; i >= 0; i--) {
        tableColumns.removeTableColumn(i);
    }
    CTTableColumn column = tableColumns.addNewTableColumn();
    // category
    column.setId(1);
    column.setName(sheet.getRow(0).getCell(0).getStringCellValue());
    // series
    for (int i = 0; i < seriesSize; i++) {
        column = tableColumns.addNewTableColumn();
        column.setId((1 + i) + 1);
        column.setName(seriesDatas.get(i).getName());
    }
}

protected CTTable getSheetTable(XSSFSheet sheet) {
    if (sheet.getTables().size() == 0) {
        // PATH: Test should invoke the next XSSFSheet.createTable(...) [step in execution path]
        XSSFTable newTable = sheet.createTable(null);
        newTable.getCTTable().addNewTableColumns();
        sheet.getTables().add(newTable);
    }
    return sheet.getTables().get(0).getCTTable();
}

