public NiceXWPFDocument merge(NiceXWPFDocument source, Iterator<NiceXWPFDocument> mergeIterator, XWPFRun run) throws Exception {
    CTBody body = source.getDocument().getBody();
    // PATH: Test should invoke the next XmlXWPFDocumentMerge.createMergeableStrings(...) [step in execution path]
    List<String> addParts = createMergeableStrings(source, mergeIterator);
    String[] startEnd = truncatedStartEndXmlFragment(body);
    XWPFParagraph paragraph = ((XWPFParagraph) (run.getParent()));
    CTP mergedContainer = paragraph.getCTP();
    CTP mergedBody = CTP.Factory.parse((((startEnd[0] + "<w:POITL>") + String.join("", addParts)) + "</w:POITL>") + startEnd[1]);
    // instead insert xml-fragment?
    mergedContainer.set(mergedBody);
    String xmlText = truncatedOverlapWP(body);
    body.set(CTBody.Factory.parse(xmlText));
    return source.generate(true);
}

protected List<String> createMergeableStrings(NiceXWPFDocument source, Iterator<NiceXWPFDocument> iterator) throws InvalidFormatException, IOException {
    List<String> addParts = new ArrayList<String>();
    if (!iterator.hasNext()) {
        return addParts;
    }
    NiceXWPFDocument next = iterator.next();
    // apply style merge once
    Map<String, String> mergeStyles = mergeStyles(source, next);
    // apply namespaces merge once
    mergeNamespaces(source, next);
    do {
        // PATH: Test should invoke the next XmlXWPFDocumentMerge.createMergeableString(...) [step in execution path]
        addParts.add(createMergeableString(source, next, mergeStyles));
        try {
            next.close();
        } catch (Exception e) {
            logger.warn("close merged doc failed!", e);
        }
        if (iterator.hasNext()) {
            next = iterator.next();
        } else {
            break;
        }
    } while (true );
    return addParts;
}

protected String createMergeableString(NiceXWPFDocument source, NiceXWPFDocument merged, Map<String, String> styleIdsMap) throws InvalidFormatException, IOException {
    CTBody mergedBody = merged.getDocument().getBody();
    // TODO For the same style, reduce the number of merges
