protected List<String> createMergeableStrings(NiceXWPFDocument source, Iterator<NiceXWPFDocument> iterator) throws InvalidFormatException, IOException {
    List<String> addParts = new ArrayList<String>();
    if (!iterator.hasNext()) {
        return addParts;
    }
    NiceXWPFDocument next = iterator.next();
