            ret.forEach((mergeNumId, abnum) -> {
                BigInteger numID = finalNumbering.addNum(finalNumbering.addAbstractNum(new XWPFAbstractNum(abnum)));
                numIdsMap.put(mergeNumId.toString(), numID.toString());
            });
            return numIdsMap;
        }
